```python
class FinancieroManipulador:
    def __init__(self, datos):
        self.datos = datos  # Lista de datos financieros
        self.tipos = ['moneda', 'moneda', 'moneda']

    def generar_datos(self):
        # Generar datos ficticios
        nuevos_datos = []
        for tipo, valor in zip(self.tipos, range(100)):
            nuevos_datos.append({
                'nombre': f'Fondo {tipo}',
                'monto': valor * 1000,  # Muestran mochileros
                'moneda': self.tipos
            })
        return nuevos_datos

    def modificar_datos(self, nuevos_datos):
        self.datos = nuevos_datos

# Ejemplo de uso
manipulador = FinancieroManipulador(datos=[
    {'nombre': 'Inversión', 'monto': 500000, 'moneda': 'USD'},
    {'nombre': 'Inversión', 'monto': 100000, 'moneda': 'USD'},
    {'nombre': 'Inversión', 'monto': 150000, 'moneda': 'USD'}
])

# Mostrar datos generados
print("Datos financieros generados:")
for dato in manipulador.generar_datos():
    print(f"{dato['nombre']} - {dato['monto']} {dato['moneda']}")

# Modificar datos
manipulador.modificar_datos([
    {'nombre': 'Inversión', 'monto': 200000, 'moneda': 'USD'},
    {'nombre': 'Inversión', 'monto': 50000, 'moneda': 'USD'}
])

# Mostrar datos modificados
print("\n Datos financieros modificados:")
for dato in manipulador.datos:
    print(f"{dato['nombre']} - {dato['monto']} {dato['moneda']}")
```

